package swedueltest

import (
	"errors"
	"testing"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

// TestWithID_ValidID tests that token validation passes when the expected JWT ID matches.
func TestWithID_ValidID(t *testing.T) {
	claims := jwt.RegisteredClaims{
		ID:        "unique-token-id-123",
		ExpiresAt: jwt.NewNumericDate(time.Now().Add(10 * time.Minute)),
	}

	validator := jwt.NewValidator(jwt.WithID("unique-token-id-123"))
	err := validator.Validate(claims)
	if err != nil {
		t.Errorf("expected no error, got: %v", err)
	}
}

// TestWithID_MismatchedID tests that validation fails when the JWT ID doesn't match.
func TestWithID_MismatchedID(t *testing.T) {
	claims := jwt.RegisteredClaims{
		ID:        "different-id",
		ExpiresAt: jwt.NewNumericDate(time.Now().Add(10 * time.Minute)),
	}

	validator := jwt.NewValidator(jwt.WithID("expected-id"))
	err := validator.Validate(claims)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenInvalidId) {
		t.Errorf("expected ErrTokenInvalidId, got: %v", err)
	}
}

// TestWithID_MissingID tests that validation fails when the jti claim is missing.
func TestWithID_MissingID(t *testing.T) {
	claims := jwt.RegisteredClaims{
		ExpiresAt: jwt.NewNumericDate(time.Now().Add(10 * time.Minute)),
	}

	validator := jwt.NewValidator(jwt.WithID("expected-id"))
	err := validator.Validate(claims)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !errors.Is(err, jwt.ErrTokenRequiredClaimMissing) {
		t.Errorf("expected ErrTokenRequiredClaimMissing, got: %v", err)
	}
}

// TestWithID_MapClaimsValid tests JWT ID validation using MapClaims.
func TestWithID_MapClaimsValid(t *testing.T) {
	claims := jwt.MapClaims{
		"jti": "map-claims-id",
		"exp": float64(time.Now().Add(10 * time.Minute).Unix()),
	}

